import os
from moler.device import DeviceFactory  # type: ignore
from taf.ul.sc.perf.tc.tc_helpers import get_absolute_path
from taf.ul.sc.perf.util.helpers import get_library_path
from taf.ul.sc.perf.testline.device_helpers import get_dsp_device_name
from taf.ul.sc.perf.util.logger import log_debug_function_info
from taf.ul.sc.unix_functionality import UnixFunctionality  # type: ignore
from taf.ul.sc.util.scp import Scp  # type: ignore


class DspStats(object):
    def __init__(self, workstation=None,
                 script_path=None,
                 dsp_script=None,
                 script_params=None,
                 script_target_path="/tmp/scripts/"):
        """
        DSP stats collecting
        :param workstation: workstation object
        :param script_path: path to script
        :param dsp_script: script name
        :param script_params: list with needed params such as nid, or enb lmp ip
        :param script_target_path: path where script will be coped
        """

        self.script_path = self._get_script_path(script_path, dsp_script)
        self.script_target_path = script_target_path
        self.script_params = script_params
        self.workstation = workstation
        self.workstation_dsp = self.create_dsp_device()

    @log_debug_function_info()
    def scp_script_to_device(self):
        """
        Copy script to device.
        """
        ws_name = self.workstation.name

        scp_obj = Scp(local_dir=os.path.dirname(self.script_path), source_file=os.path.basename(self.script_path),
                      remote_device_name=ws_name,
                      remote_dir=self.script_target_path)
        scp_obj.upload()

    def create_dsp_device(self):
        """
        Clone BTS_WS to get BTS_DSP device for collecting DSP stats.

        :return: device for collecting DSP stats
        """
        source_device_name = self.workstation.name
        device = DeviceFactory.get_cloned_device(source_device=source_device_name,
                                                 new_name=get_dsp_device_name(source_device_name))
        device_dsp = UnixFunctionality(device=device)
        return device_dsp

    @log_debug_function_info()
    def start_dsp_collecting(self):
        """
        Run script with appropriate params.
        """
        script = os.path.basename(self.script_path)
        path = os.path.join(self.script_target_path, script)

        if self.script_params:
            params = ' '.join(self.script_params)
            script_cmd = 'python {} {} '.format(path, params)
        else:
            script_cmd = 'python {} '.format(path)

        self.workstation_dsp.run_script(script_cmd=script_cmd, additional_params="&")

    @log_debug_function_info()
    def stop_dsp_collecting(self):
        """
        Kill running process.
        """
        dsp_processes = self.workstation_dsp.get_pid_of_processes(self.script_target_path)
        self.workstation_dsp.kill_process(processes=dsp_processes, options='-d sudo')

    @staticmethod
    def _get_script_path(script_path, script_name):
        """
        Get script path.
        """
        if script_path:
            script_path = get_absolute_path(script_path)
        else:
            script_path = os.path.join(get_library_path(), 'scripts', 'DSP', script_name)

        return script_path
